async function refresh(force=false,preserveSettingsForm=true){const paint=()=>render({preserveSettingsForm});const id=++refreshId;error='';if(!settings.city){days={};paint();syncPrayerWidget();return}loading=true;days=cachedDays();currentDay=dateKey();paint();try{let fetched=await loadMonth(currentDay,force);if(id!==refreshId)return;days=fetched;const tomorrow=addDays(currentDay,1);if(!days[tomorrow]){const nextMonth=await loadMonth(tomorrow);if(id!==refreshId)return;days=nextMonth}if(id!==refreshId)return;const timezone=days[currentDay]?.timezone;if(timezone&&timezone!==settings.city.timezone){updateSettings({city:{...settings.city,timezone}});currentDay=dateKey();if(!days[currentDay]){const shifted=await loadMonth(currentDay);if(id!==refreshId)return;days=shifted}}await ensureTahajjudDays();if(id!==refreshId)return }catch(cause){if(id!==refreshId)return;error=days[currentDay]?'Используется сохранённое расписание. Новые данные временно недоступны.':cause.message||'Не удалось получить расписание. Проверьте интернет.'}finally{if(id===refreshId){loading=false;paint();syncPrayerWidget()}}if(settings.weather&&!weatherBusy)refreshWeather()}
let lastTick=Date.now(),lastWeatherCheck=0,weatherRequestId=0,weatherBusy=false;
async function refreshWeather(force=false){
 if(weatherBusy)return false;
 let received=false;
 const id=++weatherRequestId,city=settings.city?{...settings.city}:null,key=weatherKey(city);
 lastWeatherCheck=Date.now();
 if(!settings.weather||!key){weather=null;weatherBusy=false;tick();return}
 weather=cachedWeather(city);weatherBusy=true;tick();
 try{const value=await loadWeather(city,{force});if(id===weatherRequestId&&settings.weather&&weatherKey(settings.city)===key){weather=value;received=Boolean(value)}}
 catch{if(id===weatherRequestId&&weatherKey(settings.city)===key)weather=cachedWeather(city)}
 finally{if(id===weatherRequestId){weatherBusy=false;tick()}}
 return received;
}
