 if(!Number.isInteger(value)||Math.abs(value)>60)return;
 const day=dateKey(),before=timingsFor(day,days)?.[key],field=usesAlHakk()?'tableOffsets':'offsets';
 const saved=updateSettings({[field]:{[key]:value}});if(!saved){toast('Не удалось сохранить поправку');return}
 reminders.reset();calendarRequestId++;
