function historyPage(){
 const start=historyPeriod==='week'?addDays(currentDay,-6):historyPeriod==='month'?currentDay.slice(0,7)+'-01':null;
 const rows=Object.keys(history).sort().reverse().filter(d=>(!start||d>=start)&&d<=currentDay&&prayers.some(([k])=>history[d][k]));
 app.innerHTML=title('Мои молитвы')+'<div class="central-day prayer-journal">'+dayPanel()+'<section class="panel section"><div class="button-row" style="margin:0 0 22px">'+[['week','Неделя'],['month','Месяц'],['all','Всё время']].map(([value,label])=>'<button type="button" class="button '+(historyPeriod===value?'':'secondary')+'" data-history-period="'+value+'" aria-pressed="'+(historyPeriod===value)+'">'+label+'</button>').join('')+'</div><div class="panel-head"><h2>История</h2><span class="muted">'+rows.length+' '+(new Intl.PluralRules('ru').select(rows.length)==='one'?'день':new Intl.PluralRules('ru').select(rows.length)==='few'?'дня':'дней')+' с отметками</span></div>'+(!rows.length?'<p class="muted">Пока нет отметок. Отметьте совершённые молитвы выше.</p>':rows.map(d=>'<div class="history-row"><span>'+new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'))+'</span><div class="history-marks">'+prayers.map(([k,n])=>'<span title="'+n+': '+(history[d][k]?'совершён':'нет отметки')+'" aria-label="'+n+': '+(history[d][k]?'отмечено':'нет отметки')+'">'+(history[d][k]?'✓':'○')+'</span>').join('')+'</div></div>').join(''))+'<p class="muted" style="margin:23px 0 0">Ваши отметки помогают видеть свой ритм. Они не оценивают поклонение.</p></section></div>';
 bindMarks();
 app.querySelectorAll('[data-history-period]').forEach(button=>button.onclick=()=>{historyPeriod=button.dataset.historyPeriod;historyPage()});
}

function calendarOccasions(){
 const events=upcomingIslamicDates(currentDay,settings.hijriOffset);
 if(!events.length)return '';
 const row=event=>'<div class="calendar-occasion"><div><strong>'+esc(event.name)+'</strong><time datetime="'+event.date+'">'+new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(event.date+'T12:00:00Z'))+(event.uncertaintyDays?' · ±'+event.uncertaintyDays+' день':'')+'</time></div><span>'+remainingDaysLabel(event.daysLeft,event.uncertaintyDays)+'</span></div>';
 return '<div class="calendar-occasions"><h3>Праздники и памятные даты</h3>'+row(events[0])+'<details class="settings-extra"><summary>Все даты</summary>'+events.slice(1).map(row).join('')+'</details><p class="muted calendar-occasion-note">Даты ориентировочные. Начало Рамадана уточняется местной общиной по наблюдению луны.</p></div>';
}
async function calendarPage(){
 const request=++calendarRequestId;
 if(!settings.city){app.innerHTML=title('Календарь')+'<section class="panel"><p class="muted">Выберите город, чтобы получить расписание.</p><button id="calendar-city" class="button">Выбрать город</button></section>';document.getElementById('calendar-city').onclick=cityDialog;return}
 calendarStart=calendarStart||currentDay;
 const valid=/^\d{4}-\d{2}-\d{2}$/.test(calendarStart)&&Number.isFinite(Date.parse(calendarStart+'T12:00:00Z'));
 if(!valid){calendarStart=currentDay}
 const count=calendarMode==='day'?1:calendarMode==='week'?7:new Date(Date.UTC(Number(calendarStart.slice(0,4)),Number(calendarStart.slice(5,7)),0)).getUTCDate();
 const start=calendarMode==='month'?calendarStart.slice(0,7)+'-01':calendarStart,end=addDays(start,count-1),cityKey=JSON.stringify([settings.city,settings.method,settings.school,settings.highLatitude,settings.tyumenTimeSource]);
 const stillCurrent=()=>request===calendarRequestId&&currentRoute==='calendar'&&cityKey===JSON.stringify([settings.city,settings.method,settings.school,settings.highLatitude,settings.tyumenTimeSource]);
 const hijri=hijriForDay(start,days,settings.hijriOffset),friday=Array.from({length:count},(_,i)=>addDays(start,i)).find(d=>new Date(d+'T12:00:00Z').getUTCDay()===5);
 app.innerHTML=title('Календарь',(usesAlHakk()?tyumenSource(start,days).label:'Время по выбранному методу')+' · '+settings.city.name)+'<section class="panel calendar-panel"><div class="button-row" style="margin:0 0 22px">'+[['day','Сегодня'],['week','Неделя'],['month','Месяц']].map(([v,n])=>'<button class="button '+(calendarMode===v?'':'secondary')+'" data-period="'+v+'" aria-pressed="'+(calendarMode===v)+'">'+n+'</button>').join('')+'</div><div class="field"><label for="calendar-date">Начальная дата</label><input id="calendar-date" type="date" min="1900-01-01" max="2200-12-31" value="'+start+'"></div>'+(hijri?'<p class="calendar-hijri"><strong>'+esc(hijri.text)+'</strong><span class="muted">'+esc(hijri.source)+(Number(settings.hijriOffset)&&!hijri.adjustmentUnavailable?' · поправка '+(settings.hijriOffset>0?'+':'')+settings.hijriOffset:'')+'</span></p>':'')+'<div class="table-scroll"><table class="calendar-table"><thead><tr><th>Дата</th>'+['Фаджр','Вос&shy;ход¹','Зухр','Аср','Маг&shy;риб','Иша'].map(n=>'<th>'+n+'</th>').join('')+'</tr></thead><tbody>'+Array.from({length:count},(_,i)=>{const d=addDays(start,i),t=timingsFor(d,days);return'<tr'+(d===currentDay?' class="calendar-today" aria-current="date"':'')+' data-calendar-day="'+d+'"><td>'+d.slice(8)+'.'+d.slice(5,7)+'</td>'+['Fajr','Sunrise','Dhuhr','Asr','Maghrib','Isha'].map(k=>'<td>'+(t?formatTime(t[k]):'—')+'</td>').join('')+'</tr>'}).join('')+'</tbody></table></div><p class="muted" style="margin-top:20px">¹ Восход не является намазом.'+(settings.mosque?' Включён ручной режим: ежедневные времена мечети одинаковы.':'')+'</p>'+(friday?'<div class="calendar-friday"><h3>Джума · '+friday.slice(8)+'.'+friday.slice(5,7)+'</h3><p class="muted">'+(settings.juma||usesAlHakk()?'Начало: <strong>'+esc(settings.juma||'13:00')+'</strong>':'Уточните время в своей мечети. Его можно сохранить в настройках.')+'</p></div>':'')+calendarOccasions()+'<h3 class="calendar-export-title">Скачать месяц</h3><div class="calendar-downloads"><button class="button secondary" id="calendar-image">Картинка</button><button class="button secondary" id="calendar-download">PDF А4</button></div><div id="calendar-status" class="muted" role="status"></div></section>';
 document.getElementById('calendar-download').onclick=()=>downloadCalendarMonth('pdf');document.getElementById('calendar-image').onclick=()=>downloadCalendarMonth('png');
 app.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{calendarMode=b.dataset.period;if(calendarMode==='day')calendarStart=currentDay;calendarPage()});
 document.getElementById('calendar-date').onchange=e=>{if(e.target.validity.valid&&e.target.value){calendarStart=e.target.value;calendarPage()}};
 if(!days[start]||!days[end]){try{document.getElementById('calendar-status').textContent='Загружаем расписание…';const first=await loadMonth(start);if(!stillCurrent())return;const last=start.slice(0,7)===end.slice(0,7)?first:await loadMonth(end);if(!stillCurrent())return;days={...days,...first,...last};calendarPage()}catch{if(stillCurrent())document.getElementById('calendar-status').textContent=usesAlHakk()?'На выбранные даты расписание Тюмени пока не подключено. Сохранённые дни отображаются.':'Расписание недоступно. Сохранённые дни отображаются.'}}
}

function qibla(){const city=settings.city,key=JSON.stringify([city?.name,city?.latitude,city?.longitude]);if(qiblaHandle?.key===key&&app.querySelector('.qibla-page'))return;stopCompass();qiblaHandle={...mountQibla(app,{city,onChooseCity:cityDialog,haptics:()=>settings.haptic}),key}}
function stopCompass(){qiblaHandle?.destroy();qiblaHandle=null}

function sourcesPage(){about()}
function about(){app.innerHTML=title('О приложении')+'<section class="panel section about-app"><span class="eyebrow">SALAH</span><h2>Рядом каждый день</h2><p class="muted">Намаз, Коран, азкары и знания.</p><p class="app-release-date">Версия '+APP_VERSION+' · обновление от <time datetime="'+esc(APP_UPDATED_AT)+'">'+esc(APP_UPDATE_DATE)+'</time></p><button type="button" class="button secondary" id="about-release-notes">Что нового</button><a class="list-button" href="#support"><span>Написать в поддержку</span><span aria-hidden="true">›</span></a></section>';document.getElementById('about-release-notes').onclick=()=>showAppRelease();}
function exportData(){let backup;try{backup=createBackup({storage:localStorage,settings,history})}catch{toast('Не удалось прочитать данные для резервной копии');return}const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='salah-backup-'+currentDay+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(backup.warnings?.length?'Копия подготовлена. Некоторые повреждённые записи пропущены.':'Резервная копия подготовлена')}
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});async function installApp(){if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('В меню браузера выберите «Установить» или «На экран Домой».')}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_prayer_schedule',description:'Прочитать доступное расписание и следующую молитву для выбранного города.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({city:settings.city?.name||null,date:currentDay,next:nextPrayer(Date.now(),currentDay,days),times:timingsFor(currentDay,days),method:methods[settings.method]})});register({name:'set_prayer_mark',description:'Сохранить личную отметку сегодняшней молитвы или убрать её.',inputSchema:{type:'object',properties:{prayer:{type:'string',enum:prayers.map(p=>p[0])},status:{type:'string',enum:['ontime','later','clear']}},required:['prayer','status'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!prayers.some(p=>p[0]===input.prayer)||!['ontime','later','clear'].includes(input.status))throw Error('Недопустимая молитва или статус');if(!markPrayer(currentDay,input.prayer,input.status==='clear'?null:input.status))throw Error('Хранилище недоступно');render();return{date:currentDay,prayer:input.prayer,status:history[currentDay][input.prayer]}}})}

function weatherDialog(){if(!settings.weather){location.hash='settings';return}const fresh=weatherFrame(weather,Date.now()).fresh;modal('<div class="modal-head"><h2>Погода</h2><button class="icon-button" data-close aria-label="Закрыть">×</button></div><h3>'+esc(settings.city?.name||'')+'</h3>'+(fresh?'<p class="muted">'+weatherName(weather.weather_code)+'<br>Температура: '+Math.round(weather.temperature_2m)+'°<br>Ощущается как: '+Math.round(weather.apparent_temperature)+'°'+(Number.isFinite(weather.wind_speed_10m)?'<br>Ветер: '+Math.round(weather.wind_speed_10m)+' м/с':'')+'<br>Данные на: '+new Intl.DateTimeFormat('ru-RU',{timeZone:settings.city?.timezone,dateStyle:'short',timeStyle:'short'}).format(new Date(weather.dataAt))+'</p>':'<p class="muted">Свежая погода пока недоступна. '+(weather?'Сохранённые данные устарели. ':'')+'Фон показывает время суток.</p>')+'<a class="text-button" href="https://open-meteo.com/" target="_blank" rel="noopener">Источник: Open-Meteo</a><button type="button" class="button secondary" id="weather-refresh" style="margin-top:16px">Обновить погоду</button><p class="muted" role="status" id="weather-refresh-result"></p>');const button=document.getElementById('weather-refresh');button.disabled=weatherBusy;button.onclick=async()=>{button.disabled=true;button.textContent='Обновляем погоду…';if(await refreshWeather(true)){if(button.isConnected&&document.getElementById('modal').open&&document.getElementById('weather-refresh')===button)weatherDialog()}else if(button.isConnected&&document.getElementById('modal').open){button.disabled=false;button.textContent='Обновить погоду';document.getElementById('weather-refresh-result').textContent='Не удалось обновить погоду. Проверьте интернет и повторите попытку.'}}}

async function importData(event){
 const input=event.target,file=input.files?.[0];input.value='';if(!file)return;
 if(file.size>5*1024*1024){toast('Файл слишком большой для резервной копии SALAH');return}
 let prepared;try{prepared=validateBackup(await file.text())}catch(error){toast(error.message||'Не удалось прочитать резервную копию');return}
 const p=prepared.preview;
 modal('<div class="modal-head"><h2>Восстановить данные?</h2><button class="icon-button" data-close aria-label="Закрыть">×</button></div><p class="muted">Настройки и история будут заменены данными из этой копии. Сначала можно сохранить текущие данные.</p><div class="backup-preview"><p>Город: '+esc(p.city||'Не выбран')+'</p><p>Дней в истории: '+p.days+' · Отметок: '+p.prayerMarks+'</p><p>Закладок Корана: '+p.bookmarks+'</p><p>Повторений азкаров: '+p.adhkarRepetitions.toLocaleString('ru-RU')+'</p></div>'+(prepared.warnings.length?'<p class="muted">'+prepared.warnings.map(esc).join('<br>')+'</p>':'')+'<div class="button-row"><button type="button" class="button secondary" id="backup-current">Сохранить текущую копию</button><button type="button" class="button" id="restore-backup">Восстановить</button></div>');
 document.getElementById('backup-current').onclick=exportData;
 document.getElementById('restore-backup').onclick=()=>{try{restoreBackup(prepared,{storage:localStorage,confirmed:true});closeModal();reminders.reset();stopCompass();stopLearning();stopAdhkar();stopQuran();quranRenderedHash=null;calendarRequestId++;days={};weatherRequestId++;weatherBusy=false;weather=null;lastWeatherCheck=0;currentDay=dateKey();location.hash='settings';refresh(false,false);toast('Данные восстановлены')}catch(error){toast(error.message||'Не удалось восстановить данные')}};
}

let calendarPdfBusy=false;
async function downloadCalendarMonth(format='pdf'){
 if(calendarPdfBusy||!settings.city)return;
 const buttons=[document.getElementById('calendar-download'),document.getElementById('calendar-image')],button=buttons[format==='pdf'?0:1],month=(calendarStart||currentDay).slice(0,7),city={...settings.city};
 const context=()=>JSON.stringify([settings.city,settings.method,settings.school,settings.highLatitude,settings.tyumenTimeSource,settings.offsets,settings.tableOffsets]);
 const snapshot=context(),school=Number(settings.school);calendarPdfBusy=true;buttons.forEach(b=>{if(b)b.disabled=true});if(button)button.textContent='Готовим…'
 try{
  const [firstDays,hanafiDays]=await Promise.all([loadMonth(month+'-01',false,0),loadMonth(month+'-01',false,1)]);
  if(context()!==snapshot||currentRoute!=='calendar')return;
  const fullDays={...days,...(school===1?hanafiDays:firstDays)},rows=monthRows(month,day=>{const first=timingsFor(day,firstDays,0),hanafi=timingsFor(day,hanafiDays,1);return first&&hanafi?{...timingsFor(day,fullDays,school),AsrFirst:first.Asr,AsrHanafi:hanafi.Asr}:null},time=>formatTime(time,city.timezone));
  const source=usesAlHakk()?tyumenSource(month+'-01',fullDays).label:methods[settings.method];
  const file=await createMonthFile({month,city:city.name,rows,source,localAsr:usesAlHakk()},format);
  if(context()!==snapshot||currentRoute!=='calendar')return;
  const fileUrl=URL.createObjectURL(file),name='SALAH-'+month+'-A4.'+format;
  modal('<div class="modal-head"><h2>Расписание на месяц</h2><button class="icon-button" data-close aria-label="Закрыть">×</button></div>'+(format==='png'?'<img class="calendar-export-preview" src="'+fileUrl+'" alt="Расписание намаза на полный месяц">':'<p class="muted">Полный месяц на одном листе А4 с логотипом SALAH.</p>')+'<a class="button" href="'+fileUrl+'" download="'+name+'">'+(format==='pdf'?'Скачать PDF':'Скачать картинку')+'</a>');
  setTimeout(()=>URL.revokeObjectURL(fileUrl),300000);
 }catch(error){toast(error.message||'Не удалось подготовить расписание.')}
 finally{calendarPdfBusy=false;buttons.forEach((b,i)=>{if(b){b.disabled=false;b.textContent=i===0?'PDF А4':'Картинка'}})}
}
